//! 🧬️ Transparent dispatch for the OS config mutation vocabularies. Concrete payloads, behavior,
//! and tests live in direct semantic leaves; shared codecs live with their schema. This root only
//! wraps leaf payloads and delegates descriptor registration generated by `dsl::Mutations`.

use super::super::OpeningPreferences;
use serde::{Deserialize, Serialize};
use semio_framework_value_derive::{FromValue, ToValue};

//#region 🔖️Opening
pub use super::clear_default_app::{clear_default_app, ClearDefaultApp};
pub use super::set_default_app::{set_default_app, SetDefaultApp};

/// 🎚️ Typed, invertible opening-preferences mutation vocabulary.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize, ToValue, FromValue, dsl::Mutations)]
#[serde(tag = "mutation", rename_all = "camelCase")]
#[value(tag = "mutation", rename_all = "camelCase")]
#[mutations(snapshot = OpeningPreferences, diff = OpeningPreferences, schema = "os.config.opening")]
pub enum OpeningConfigMutation {
    SetDefaultApp(SetDefaultApp),
    ClearDefaultApp(ClearDefaultApp),
}
//#endregion 🔖️Opening

//#region 🔖️MergePolicy
pub use super::change_merge_policy::{
    apply_merge_policy_config_mutation, apply_merge_policy_config_mutation_reporting, change_merge_policy, decode_merge_policy_config_mutation_json, decode_merge_policy_setting_json, encode_merge_policy_setting_json,
    inverse_merge_policy_config_mutation, inverse_merge_policy_config_mutation_steps, ChangeMergePolicy, MergePolicySetting, MERGE_POLICY_CONFIG_SCHEMA,
};

/// 🛡️ Typed, invertible merge-policy mutation vocabulary.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize, ToValue, FromValue, dsl::Mutations)]
#[serde(tag = "mutation", rename_all = "camelCase")]
#[value(tag = "mutation", rename_all = "camelCase")]
#[mutations(snapshot = MergePolicySetting, diff = MergePolicySetting, schema = "os.config.merge-policy")]
pub enum MergePolicyConfigMutation {
    ChangeMergePolicy(ChangeMergePolicy),
}
//#endregion 🔖️MergePolicy

//#region 🔖️Identity
pub use super::sign_in::{
    apply_identity_config_mutation, apply_identity_config_mutation_reporting, decode_identity_config_mutation_json, decode_identity_setting_json, encode_identity_setting_json, inverse_identity_config_mutation,
    inverse_identity_config_mutation_steps, sign_in, Identity, IdentitySetting, SignIn, IDENTITY_CONFIG_SCHEMA,
};
pub use super::sign_out::{sign_out, SignOut};

/// 🪪️ Typed, invertible identity mutation vocabulary.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize, ToValue, FromValue, dsl::Mutations)]
#[serde(tag = "mutation", rename_all = "camelCase")]
#[value(tag = "mutation", rename_all = "camelCase")]
#[mutations(snapshot = IdentitySetting, diff = IdentitySetting, schema = "os.config.identity")]
pub enum IdentityConfigMutation {
    SignIn(SignIn),
    SignOut(SignOut),
}
//#endregion 🔖️Identity

//#region 🔖️Registry
/// 🪪️ Registers every OS config mutation descriptor through the derive-generated registries.
pub fn register_os_config_mutation_descriptors() -> Result<(), semio_framework_os_kernel::MutationDescriptorError> {
    register_opening_config_mutation_descriptors(semio_framework_os_kernel::StateClass::Config)?;
    register_merge_policy_config_mutation_descriptors(semio_framework_os_kernel::StateClass::Config)?;
    register_identity_config_mutation_descriptors(semio_framework_os_kernel::StateClass::Config)
}
//#endregion 🔖️Registry
